import api from './api';

export const documentService = {
  // GET documentos privados (con autenticación)
  getAll: async (filters = {}) => {
    const params = new URLSearchParams();
    if (filters.client_id) params.append('client_id', filters.client_id);
    if (filters.year) params.append('year', filters.year);
    if (filters.month) params.append('month', filters.month);
    if (filters.folder_id) params.append('folder_id', filters.folder_id);
    if (filters.search) params.append('search', filters.search);
    if (filters.is_public !== undefined) params.append('is_public', filters.is_public);

    const response = await api.get(`/documents?${params.toString()}`);
    return response.data;
  },

  // GET documentos públicos (sin autenticación)
  getPublic: async (filters = {}) => {
    const params = new URLSearchParams();
    if (filters.year) params.append('year', filters.year);
    if (filters.month) params.append('month', filters.month);
    if (filters.search) params.append('search', filters.search);

    const response = await api.get(`/documents/public/list?${params.toString()}`);
    return response.data;
  },

  // GET documentos de un cliente específico (Admin/Super Admin)
  getClientAllDocuments: async (clientId, filters = {}) => {
    const params = new URLSearchParams();
    if (filters.year) params.append('year', filters.year);
    if (filters.month) params.append('month', filters.month);
    if (filters.folder_id) params.append('folder_id', filters.folder_id);
    if (filters.search) params.append('search', filters.search);
    if (filters.document_type) params.append('document_type', filters.document_type);
    if (filters.is_public !== undefined) params.append('is_public', filters.is_public);

    const response = await api.get(
      `/documents/client/${clientId}/all?${params.toString()}`
    );
    return response.data;
  },

  // GET carpetas
  getFolders: async (clientId, parentId = null) => {
    const params = new URLSearchParams();
    if (parentId) params.append('parent_id', parentId);

    const response = await api.get(`/documents/folders/${clientId}?${params.toString()}`);
    return response.data;
  },

  // POST crear carpeta
  createFolder: async (folderData) => {
    const response = await api.post('/documents/folders', folderData);
    return response.data;
  },

  // POST subir documento
  upload: async (formData, onProgress) => {
    const response = await api.post('/documents/upload', formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
      onUploadProgress: onProgress,
    });
    return response.data;
  },

  // GET descargar documento
  download: async (id) => {
    const response = await api.get(`/documents/${id}/download`, {
      responseType: 'blob',
    });
    return response.data;
  },

  // DELETE eliminar documento
  delete: async (id) => {
    const response = await api.delete(`/documents/${id}`);
    return response.data;
  },
};
